#include "Hfe.h"
#include "Constants.h"
#include "../../Sources/AtomicImageWriter.h"
#include <RetroMediaLab/MediaEngine/Diagnostics.h>
#include <algorithm>
#include <set>
namespace RetroMediaLab::MediaEngine::Hfe {
namespace {
using namespace Constants;
void word(std::vector<std::uint8_t>& bytes,std::size_t offset,std::uint64_t value){if(value>MaxField)throw MediaError(DiagnosticCode::HfeLimit);bytes[offset]=std::uint8_t(value);bytes[offset+1]=std::uint8_t(value>>BitsPerByte);}
void validate(const Image& i){if(i.revision!=Revision)throw MediaError(DiagnosticCode::HfeRevision,{std::to_string(i.revision)});if(i.cylinders<1||i.cylinders>std::int32_t(MaxCylinder)||i.heads<1||i.heads>std::int32_t(MaxHeads)||!i.bitRate)throw MediaError(DiagnosticCode::HfeGeometry);if(i.tracks.empty())throw MediaError(DiagnosticCode::HfeTracks);std::set<std::pair<std::int32_t,std::int32_t>> seen;for(const auto& t:i.tracks){if(t.cylinder<0||t.cylinder>=i.cylinders||t.head<0||t.head>=i.heads)throw MediaError(DiagnosticCode::HfeTrackAddress);if(!seen.emplace(t.cylinder,t.head).second)throw MediaError(DiagnosticCode::HfeDuplicateTrack,{std::to_string(t.cylinder),std::to_string(t.head)});}}
void writeBytes(const std::vector<std::uint8_t>& bytes,const std::filesystem::path& path,std::stop_token token){writeAtomicImage(path,[&](const ImageOutput& output,std::stop_token stop){checkCancellation(stop);output(bytes);},token);}
}
std::vector<std::uint8_t> header(const Image& i){using namespace Constants;if(i.cylinders<0||i.cylinders>std::int32_t(MaxCylinder)||i.heads<0||i.heads>std::int32_t(MaxCylinder))throw MediaError(DiagnosticCode::HfeLimit);std::vector<std::uint8_t> result(BlockSize,HeaderPadding);std::copy(Signature.begin(),Signature.end(),result.begin());result[RevisionOffset]=i.revision;result[CylinderOffset]=std::uint8_t(i.cylinders);result[HeadOffset]=std::uint8_t(i.heads);result[EncodingOffset]=i.encoding;word(result,BitRateOffset,i.bitRate);word(result,RpmOffset,0);result[InterfaceOffset]=Unknown;result[ProtectedOffset]=WriteProtected;word(result,TableOffset,1);result[WriteAllowedOffset]=i.writeProtected?WriteForbidden:WriteAllowed;result[SingleStepOffset]=SingleStep;return result;}
void appendTrackData(std::vector<std::uint8_t>& destination,const std::vector<std::vector<std::uint8_t>>& packed,std::size_t sideLength,std::uint8_t padding){using namespace Constants;const auto blocks=(sideLength+SideChunk-1)/SideChunk;for(std::size_t block=0;block<blocks;++block)for(std::size_t head=0;head<MaxHeads;++head){const auto offset=block*SideChunk;const auto count=head<packed.size()&&offset<packed[head].size()?std::min(SideChunk,packed[head].size()-offset):0;if(count)destination.insert(destination.end(),packed[head].begin()+std::ptrdiff_t(offset),packed[head].begin()+std::ptrdiff_t(offset+count));destination.insert(destination.end(),SideChunk-count,padding);}}
std::vector<std::uint8_t> build(const Image& i){using namespace Constants;validate(i);const auto tableBlocks=std::max(std::size_t(1),(i.cylinders*EntrySize+BlockSize-1)/BlockSize);std::vector<std::uint8_t> table(tableBlocks*BlockSize,HeaderPadding),body;std::size_t dataBlock=1+tableBlocks;
 for(std::int32_t cylinder=0;cylinder<i.cylinders;++cylinder){std::vector<std::vector<std::uint8_t>> packed;bool present=false;std::size_t length=0;for(std::int32_t head=0;head<i.heads;++head){const auto found=std::find_if(i.tracks.begin(),i.tracks.end(),[&](const auto&t){return t.cylinder==cylinder&&t.head==head;});present|=found!=i.tracks.end();packed.push_back(found==i.tracks.end()?std::vector<std::uint8_t>{}:pack(found->bits));length=std::max(length,packed.back().size());}if(!present)throw MediaError(DiagnosticCode::HfeMissingTrack,{std::to_string(cylinder)});if(!length||length>MaxSide)throw MediaError(DiagnosticCode::HfeTrackLength,{std::to_string(cylinder)});word(table,cylinder*EntrySize,dataBlock);word(table,cylinder*EntrySize+LengthOffset,length*MaxHeads);appendTrackData(body,packed,length,TrackPadding);dataBlock+=(length+SideChunk-1)/SideChunk;}
 auto result=header(i);result.insert(result.end(),table.begin(),table.end());result.insert(result.end(),body.begin(),body.end());return result;
}
std::vector<std::uint8_t> build(std::span<const Encoding::DiskTrack> tracks){using namespace Constants;if(tracks.empty())throw MediaError(DiagnosticCode::HfeTracks);Image i;std::optional<std::string> encoder;std::optional<std::uint16_t> rate;for(const auto& t:tracks){if(encoder&&*encoder!=t.track.encoderId)throw MediaError(DiagnosticCode::HfeUniformEncoding);encoder=t.track.encoderId;const auto value=t.cellTicks?NanosecondsPerSecond/(std::uint64_t(BitsPerDataBit)*TickNanoseconds*NanosecondsPerMicrosecond*t.cellTicks):0;if(!value||value>MaxField)throw MediaError(DiagnosticCode::HfeTiming);if(rate&&*rate!=value)throw MediaError(DiagnosticCode::HfeUniformRate);rate=std::uint16_t(value);if(t.cylinder==std::numeric_limits<std::int32_t>::max()||t.head==std::numeric_limits<std::int32_t>::max())throw MediaError(DiagnosticCode::HfeLimit);i.cylinders=std::max(i.cylinders,t.cylinder+1);i.heads=std::max(i.heads,t.head+1);i.tracks.push_back(uniformTrack(t.cylinder,t.head,t.track.bits,t.cellTicks));}
 i.encoding=*encoder==IsoMfmId?IsoMfm:*encoder==AmigaMfmId?AmigaMfm:*encoder==IsoFmId?IsoFm:Unknown;if(i.encoding==Unknown)throw MediaError(DiagnosticCode::HfeEncoding,{*encoder});i.bitRate=*rate;return build(i);
}
void write(const Image& image,const std::filesystem::path& path,std::stop_token token){writeBytes(build(image),path,token);}
void write(std::span<const Encoding::DiskTrack> tracks,const std::filesystem::path& path,std::stop_token token){writeBytes(build(tracks),path,token);}
void write(const Flux::ProtectedTrackImage& image,const Metadata& metadata,const std::filesystem::path& path,std::stop_token token){writeBytes(build(image,metadata),path,token);}
}
